#!/usr/bin/env bun
/**
 * WisdomFrameUpdater.ts - Wisdom Frame management for PAI
 *
 * Stores and retrieves domain-specific observations that persist across
 * sessions, building up a compound knowledge layer about how Ivan works.
 *
 * Used by the Algorithm's LEARN phase (WRITE) and OBSERVE phase (READ).
 *
 * COMMANDS:
 *   --add    --domain X --observation "Y" --type Z  Add observation
 *   --list   [--domain X]                           List frames/observations
 *   --read   --domain X                             Read full domain frame
 *   --domains                                       List all known domains
 *
 * OBSERVATION TYPES:
 *   anti-pattern       Something that leads to problems
 *   contextual-rule    How Ivan prefers things done
 *   prediction         Expected request pattern
 *   principle          Confirmed core principle
 *
 * EXAMPLES:
 *   bun WisdomFrameUpdater.ts --add --domain development --observation "Ivan prefers MVP before ideal" --type contextual-rule
 *   bun WisdomFrameUpdater.ts --list --domain development
 *   bun WisdomFrameUpdater.ts --read --domain development
 *   bun WisdomFrameUpdater.ts --domains
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync, readdirSync } from 'fs';
import { join } from 'path';

// ── Types ──

type ObservationType = 'anti-pattern' | 'contextual-rule' | 'prediction' | 'principle';

interface Observation {
  type: ObservationType;
  observation: string;
  timestamp: string;
  session_id?: string;
  confirmed: number;  // how many times this has been reinforced
}

interface WisdomFrame {
  domain: string;
  updated: string;
  observations: Observation[];
}

// ── Config ──

const CLAUDE_DIR = process.env.PAI_DIR || join(process.env.HOME!, '.claude');
const WISDOM_DIR = join(CLAUDE_DIR, 'MEMORY', 'WISDOM');

const KNOWN_DOMAINS = [
  'development',
  'deployment',
  'communication',
  'system',
  'workflow',
  'learning',
];

const TYPE_ICONS: Record<ObservationType, string> = {
  'anti-pattern': '⚠️',
  'contextual-rule': '📌',
  'prediction': '🔮',
  'principle': '💎',
};

// ── Helpers ──

function ensureWisdomDir(): void {
  if (!existsSync(WISDOM_DIR)) mkdirSync(WISDOM_DIR, { recursive: true });
}

function getFramePath(domain: string): string {
  return join(WISDOM_DIR, `${domain}.json`);
}

function loadFrame(domain: string): WisdomFrame {
  const path = getFramePath(domain);
  if (!existsSync(path)) {
    return { domain, updated: new Date().toISOString(), observations: [] };
  }
  return JSON.parse(readFileSync(path, 'utf-8')) as WisdomFrame;
}

function saveFrame(frame: WisdomFrame): void {
  ensureWisdomDir();
  frame.updated = new Date().toISOString();
  writeFileSync(getFramePath(frame.domain), JSON.stringify(frame, null, 2), 'utf-8');
}

function listDomainFiles(): string[] {
  if (!existsSync(WISDOM_DIR)) return [];
  return readdirSync(WISDOM_DIR)
    .filter(f => f.endsWith('.json'))
    .map(f => f.replace('.json', ''));
}

// ── Commands ──

function cmdAdd(domain: string, observation: string, type: ObservationType, sessionId?: string): void {
  if (!domain || !observation || !type) {
    console.error('Usage: --add --domain X --observation "Y" --type Z');
    console.error('Types: anti-pattern | contextual-rule | prediction | principle');
    process.exit(1);
  }

  const validTypes: ObservationType[] = ['anti-pattern', 'contextual-rule', 'prediction', 'principle'];
  if (!validTypes.includes(type)) {
    console.error(`Invalid type: ${type}. Valid: ${validTypes.join(' | ')}`);
    process.exit(1);
  }

  const frame = loadFrame(domain);

  // Check for duplicate (by observation text similarity)
  const existing = frame.observations.find(o =>
    o.observation.toLowerCase() === observation.toLowerCase()
  );

  if (existing) {
    existing.confirmed += 1;
    existing.timestamp = new Date().toISOString();
    console.log(`[WisdomFrameUpdater] Reinforced existing: "${observation}" (confirmed: ${existing.confirmed}x)`);
  } else {
    frame.observations.push({
      type,
      observation,
      timestamp: new Date().toISOString(),
      session_id: sessionId,
      confirmed: 1,
    });
    console.log(`[WisdomFrameUpdater] Added to domain '${domain}': ${TYPE_ICONS[type]} [${type}] "${observation}"`);
  }

  saveFrame(frame);
  console.log(`[WisdomFrameUpdater] Frame saved → ${getFramePath(domain)}`);
}

function cmdList(domain?: string): void {
  const domains = domain ? [domain] : listDomainFiles();

  if (domains.length === 0) {
    console.log('No wisdom frames found. Add observations with --add.');
    return;
  }

  for (const d of domains) {
    const frame = loadFrame(d);
    console.log(`\n── ${d.toUpperCase()} (${frame.observations.length} observations) ──`);
    console.log(`   Updated: ${frame.updated}`);

    if (frame.observations.length === 0) {
      console.log('   (empty)');
      continue;
    }

    // Group by type
    const byType: Record<ObservationType, Observation[]> = {
      'principle': [],
      'contextual-rule': [],
      'anti-pattern': [],
      'prediction': [],
    };
    for (const obs of frame.observations) {
      byType[obs.type].push(obs);
    }

    for (const [type, obs] of Object.entries(byType)) {
      if (obs.length === 0) continue;
      console.log(`\n   ${TYPE_ICONS[type as ObservationType]} ${type.toUpperCase()}:`);
      for (const o of obs) {
        const conf = o.confirmed > 1 ? ` (×${o.confirmed})` : '';
        console.log(`     • ${o.observation}${conf}`);
      }
    }
  }
}

function cmdRead(domain: string): void {
  if (!domain) {
    console.error('Usage: --read --domain X');
    process.exit(1);
  }

  const frame = loadFrame(domain);

  if (frame.observations.length === 0) {
    console.log(`No observations for domain: ${domain}`);
    return;
  }

  // Output as compact context block suitable for injection into OBSERVE
  console.log(`=== WISDOM FRAME: ${domain.toUpperCase()} ===`);
  console.log(`Updated: ${frame.updated} | ${frame.observations.length} observations\n`);

  for (const obs of frame.observations) {
    const conf = obs.confirmed > 1 ? ` [confirmed ×${obs.confirmed}]` : '';
    console.log(`${TYPE_ICONS[obs.type]} [${obs.type}] ${obs.observation}${conf}`);
  }
}

function cmdDomains(): void {
  const domains = listDomainFiles();
  if (domains.length === 0) {
    console.log('No wisdom frames yet. Known domain names:');
    for (const d of KNOWN_DOMAINS) console.log(`  - ${d}`);
    return;
  }

  console.log('Wisdom frames on disk:');
  for (const d of domains) {
    const frame = loadFrame(d);
    console.log(`  ${d}: ${frame.observations.length} observations (updated ${frame.updated.split('T')[0]})`);
  }
}

// ── Main ──

const args = process.argv.slice(2);

if (args.includes('--add')) {
  const domainIdx = args.indexOf('--domain');
  const obsIdx = args.indexOf('--observation');
  const typeIdx = args.indexOf('--type');
  const sessionIdx = args.indexOf('--session');

  cmdAdd(
    domainIdx >= 0 ? args[domainIdx + 1] : '',
    obsIdx >= 0 ? args[obsIdx + 1] : '',
    typeIdx >= 0 ? args[typeIdx + 1] as ObservationType : '' as ObservationType,
    sessionIdx >= 0 ? args[sessionIdx + 1] : undefined,
  );
} else if (args.includes('--list')) {
  const domainIdx = args.indexOf('--domain');
  cmdList(domainIdx >= 0 ? args[domainIdx + 1] : undefined);
} else if (args.includes('--read')) {
  const domainIdx = args.indexOf('--domain');
  cmdRead(domainIdx >= 0 ? args[domainIdx + 1] : '');
} else if (args.includes('--domains')) {
  cmdDomains();
} else {
  console.log(`WisdomFrameUpdater — PAI compound knowledge across sessions

USAGE:
  bun WisdomFrameUpdater.ts --add --domain X --observation "Y" --type Z
  bun WisdomFrameUpdater.ts --list [--domain X]
  bun WisdomFrameUpdater.ts --read --domain X
  bun WisdomFrameUpdater.ts --domains

TYPES: anti-pattern | contextual-rule | prediction | principle
DOMAINS: ${KNOWN_DOMAINS.join(' | ')} (or any custom name)`);
}

#!/usr/bin/env bun
/**
 * WisdomExtractor.ts - Auto-extract Wisdom Frame observations from session transcripts
 *
 * Called during the Algorithm's LEARN phase to automatically extract domain
 * observations about how Ivan works, then persist them via WisdomFrameUpdater.
 *
 * This is the automated WRITE side of the Wisdom Frames dual loop:
 *   OBSERVE reads MEMORY/WISDOM/ → WisdomExtractor writes MEMORY/WISDOM/
 *
 * USAGE:
 *   bun WisdomExtractor.ts --transcript /path/to/transcript.jsonl
 *   bun WisdomExtractor.ts --session SESSION_ID
 *   bun WisdomExtractor.ts --dry-run --transcript /path/...   (preview without writing)
 *
 * OUTPUT:
 *   Lists extracted observations and writes them via WisdomFrameUpdater.ts
 *   Returns exit 0 on success, exit 1 on failure
 */

import { existsSync, readFileSync } from 'fs';
import { join } from 'path';
import { inference } from './Inference';
import { execSync } from 'child_process';

// ── Config ──

const CLAUDE_DIR = process.env.PAI_DIR || join(process.env.HOME!, '.claude');
const TOOLS_DIR = join(CLAUDE_DIR, 'skills', 'PAI', 'Tools');
const WISDOM_UPDATER = join(TOOLS_DIR, 'WisdomFrameUpdater.ts');

const VALID_DOMAINS = ['development', 'deployment', 'communication', 'system', 'workflow', 'learning'];
const VALID_TYPES = ['anti-pattern', 'contextual-rule', 'prediction', 'principle'];

const MAX_TRANSCRIPT_CHARS = 6000; // Keep Haiku prompt reasonable
const MIN_OBSERVATION_LENGTH = 20;
const MAX_OBSERVATIONS_PER_SESSION = 3;

// ── Types ──

interface ExtractedObservation {
  domain: string;
  type: string;
  observation: string;
}

interface HookInput {
  session_id: string;
  transcript_path: string;
}

// ── Transcript Reader ──

function readTranscript(path: string): string {
  if (!existsSync(path)) return '';

  try {
    const content = readFileSync(path, 'utf-8');
    const lines = content.trim().split('\n');
    const exchanges: string[] = [];

    for (const line of lines) {
      if (!line.trim()) continue;
      try {
        const entry = JSON.parse(line);

        if (entry.type === 'user' && entry.message?.content) {
          const text = typeof entry.message.content === 'string'
            ? entry.message.content
            : Array.isArray(entry.message.content)
              ? entry.message.content.filter((c: any) => c.type === 'text').map((c: any) => c.text).join(' ')
              : '';
          if (text.trim()) exchanges.push(`User: ${text.slice(0, 300)}`);
        }

        if (entry.type === 'assistant' && entry.message?.content) {
          const text = typeof entry.message.content === 'string'
            ? entry.message.content
            : Array.isArray(entry.message.content)
              ? entry.message.content.filter((c: any) => c.type === 'text').map((c: any) => c.text).join(' ')
              : '';
          if (text) {
            // Extract key summary lines from algorithm output
            const taskMatch = text.match(/🗒️\s*TASK:\s*([^\n]+)/);
            const summaryMatch = text.match(/🗣️[^:]+:\s*([^\n]+)/);
            const summary = taskMatch
              ? `Navi: [${taskMatch[1].trim()}] ${summaryMatch ? summaryMatch[1].slice(0, 150) : ''}`
              : `Navi: ${text.slice(0, 200)}`;
            exchanges.push(summary);
          }
        }
      } catch {}
    }

    const full = exchanges.join('\n');
    // Take last portion if too long
    return full.length > MAX_TRANSCRIPT_CHARS
      ? '...[earlier context omitted]...\n' + full.slice(-MAX_TRANSCRIPT_CHARS)
      : full;
  } catch {
    return '';
  }
}

function findTranscriptBySession(sessionId: string): string | null {
  const projectsDir = join(CLAUDE_DIR, 'projects');
  if (!existsSync(projectsDir)) return null;

  // Look for transcript in projects directory
  const { readdirSync } = await import('fs').catch(() => require('fs'));
  try {
    const dirs = readdirSync(projectsDir);
    for (const dir of dirs) {
      const candidate = join(projectsDir, dir, `${sessionId}.jsonl`);
      if (existsSync(candidate)) return candidate;
    }
  } catch {}
  return null;
}

// ── Extraction ──

const EXTRACT_SYSTEM_PROMPT = `You are analyzing an AI assistant (Navi) work session with Ivan to extract persistent observations.

Ivan is a solo entrepreneur working in WSL2 Ubuntu / Windows Terminal. Navi is his PAI (Personal AI Infrastructure) assistant.

Your job: Extract 0-${MAX_OBSERVATIONS_PER_SESSION} observations that would be USEFUL TO REMEMBER in future sessions.

EXTRACTION RULES:
1. Only extract SPECIFIC, ACTIONABLE observations about Ivan's working style or preferences
2. Skip generic/obvious things ("Ivan likes quality work")
3. Skip one-off events that won't repeat
4. Focus on PATTERNS that will recur
5. If nothing genuinely new → return empty array []

VALID DOMAINS: development | deployment | communication | system | workflow | learning
VALID TYPES:
  - anti-pattern: behavior that consistently causes problems
  - contextual-rule: how Ivan specifically prefers things done
  - prediction: a pattern in what Ivan will ask for
  - principle: a core working value Ivan has demonstrated

OUTPUT FORMAT (JSON array only, no other text):
[
  {
    "domain": "development",
    "type": "contextual-rule",
    "observation": "specific factual statement, 10-30 words"
  }
]

EXAMPLES of GOOD observations:
- {"domain":"workflow","type":"contextual-rule","observation":"Ivan asks 'what else can we check?' after fixing bugs — likes comprehensive auditing"}
- {"domain":"system","type":"anti-pattern","observation":"PAI hooks silently fail when env vars differ between WSL2 and native Linux — always verify platform vars"}
- {"domain":"development","type":"prediction","observation":"After finding one bug in a subsystem, Ivan will ask to audit the whole subsystem"}

EXAMPLES of BAD observations (too generic):
- "Ivan likes good work" — too vague
- "Navi should fix bugs" — not about Ivan
- "WSL2 exists" — not actionable`;

async function extractObservations(transcript: string): Promise<ExtractedObservation[]> {
  if (!transcript.trim()) {
    console.error('[WisdomExtractor] Empty transcript, skipping extraction');
    return [];
  }

  const result = await inference({
    systemPrompt: EXTRACT_SYSTEM_PROMPT,
    userPrompt: `SESSION TRANSCRIPT:\n${transcript}\n\nExtract 0-${MAX_OBSERVATIONS_PER_SESSION} observations. Return [] if nothing new.`,
    expectJson: true,
    timeout: 15000,
    level: 'fast',
  });

  if (!result.success || !result.parsed) {
    console.error(`[WisdomExtractor] Inference failed: ${result.error}`);
    return [];
  }

  const parsed = result.parsed;
  if (!Array.isArray(parsed)) {
    console.error('[WisdomExtractor] Response not an array, skipping');
    return [];
  }

  // Validate each observation
  return parsed.filter((obs: any) => {
    if (!obs.domain || !obs.type || !obs.observation) return false;
    if (!VALID_DOMAINS.includes(obs.domain)) return false;
    if (!VALID_TYPES.includes(obs.type)) return false;
    if (obs.observation.length < MIN_OBSERVATION_LENGTH) return false;
    return true;
  }) as ExtractedObservation[];
}

// ── Writer ──

function writeObservation(obs: ExtractedObservation, sessionId: string, dryRun: boolean): boolean {
  const cmd = `bun "${WISDOM_UPDATER}" --add --domain "${obs.domain}" --observation "${obs.observation.replace(/"/g, '\\"')}" --type "${obs.type}" --session "${sessionId}"`;

  if (dryRun) {
    console.log(`  [DRY RUN] Would call: ${cmd}`);
    return true;
  }

  try {
    execSync(cmd, { cwd: TOOLS_DIR, stdio: 'pipe' });
    return true;
  } catch (err) {
    console.error(`[WisdomExtractor] Failed to write observation: ${err}`);
    return false;
  }
}

// ── Main ──

async function main() {
  const args = process.argv.slice(2);
  const dryRun = args.includes('--dry-run');

  let transcriptPath: string | null = null;
  let sessionId = 'unknown';

  const transcriptIdx = args.indexOf('--transcript');
  const sessionIdx = args.indexOf('--session');

  if (transcriptIdx >= 0) {
    transcriptPath = args[transcriptIdx + 1];
    sessionId = transcriptPath?.split('/').pop()?.replace('.jsonl', '') || 'unknown';
  } else if (sessionIdx >= 0) {
    sessionId = args[sessionIdx + 1];
    transcriptPath = findTranscriptBySession(sessionId);
    if (!transcriptPath) {
      console.error(`[WisdomExtractor] Could not find transcript for session: ${sessionId}`);
      process.exit(1);
    }
  } else {
    console.error(`Usage:
  bun WisdomExtractor.ts --transcript /path/to/transcript.jsonl
  bun WisdomExtractor.ts --session SESSION_ID
  bun WisdomExtractor.ts --dry-run --transcript /path/...`);
    process.exit(1);
  }

  if (!transcriptPath || !existsSync(transcriptPath)) {
    console.error(`[WisdomExtractor] Transcript not found: ${transcriptPath}`);
    process.exit(1);
  }

  console.error(`[WisdomExtractor] Reading transcript: ${transcriptPath}`);
  const transcript = readTranscript(transcriptPath);
  console.error(`[WisdomExtractor] Transcript: ${transcript.length} chars`);

  console.error('[WisdomExtractor] Running Haiku extraction...');
  const observations = await extractObservations(transcript);

  if (observations.length === 0) {
    console.log('[WisdomExtractor] No new observations extracted — session had no new wisdom');
    process.exit(0);
  }

  console.log(`\n[WisdomExtractor] Extracted ${observations.length} observation(s):`);
  let written = 0;
  for (const obs of observations) {
    const icon = obs.type === 'anti-pattern' ? '⚠️' : obs.type === 'principle' ? '💎' : obs.type === 'prediction' ? '🔮' : '📌';
    console.log(`  ${icon} [${obs.domain}/${obs.type}] "${obs.observation}"`);
    if (writeObservation(obs, sessionId, dryRun)) written++;
  }

  if (!dryRun) {
    console.log(`\n[WisdomExtractor] ✅ Written ${written}/${observations.length} observations to MEMORY/WISDOM/`);
  }

  process.exit(0);
}

main().catch(err => {
  console.error(`[WisdomExtractor] Fatal error: ${err}`);
  process.exit(1);
});

